const url = require('url');
const REPO = $env.REPO_DIR || '/home/node/repo';
const L = await import(url.pathToFileURL(REPO + '/automation/lib/w10.mjs').href);
const j = $json; const op = L.classifyOp(j);
const sp = L.parseSlotPayload((j.msg && (j.msg.payload || j.msg.list_id)) || '');
return { json: { ...j, op, pick: sp, booking_id: (sp && sp.booking_id) || (j.booking && j.booking.id) || null, lead_id: j.lead ? j.lead.id : null } };

const url = require('url');
const REPO = $env.REPO_DIR || '/home/node/repo';
const L = await import(url.pathToFileURL(REPO + '/automation/lib/w10.mjs').href);
const j = $('Merge context').item.json;
const o = L.offerMessage({ booking: j.bk, lead: j.ld, broker: j.br, brand: j.brand, slots: $json.slots || [], now_ms: Date.now(), last_inbound_ms: j.last_inbound_ms, reason: j.op });
let wa = null;
if (o.kind === 'list_session') wa = { type: 'interactive', interactive: { type: 'list', body: { text: o.body }, action: { button: 'See times', sections: [{ title: 'Open times', rows: o.rows }] } } };
else if (o.kind === 'flow_session') wa = { type: 'interactive', interactive: { type: 'flow', body: { text: 'No problem. Pick a new time below.' }, action: { name: 'flow', parameters: { flow_message_version: '3', flow_id: j.brand.booking_flow_id || $env.RESCHEDULE_FLOW_ID, flow_cta: 'Pick a new time', flow_action: 'data_exchange', flow_token: 'resched:' + j.bk.id } } } };
else if (o.kind === 'template') { const comps = [{ type: 'body', parameters: o.vars.map((t) => ({ type: 'text', text: String(t) })) }]; (o.buttons || []).forEach((p, i) => comps.push({ type: 'button', sub_type: 'quick_reply', index: String(i), parameters: [{ type: 'payload', payload: p }] })); if (o.template === 'reschedule_offer_v2') comps.push({ type: 'button', sub_type: 'flow', index: '0', parameters: [{ type: 'action', action: { flow_token: 'resched:' + j.bk.id } }] }); wa = { type: 'template', template: { name: o.template, language: { code: 'en' }, components: comps } }; }
return { json: { ...j, offer: o, wa: wa ? { messaging_product: 'whatsapp', to: j.ld.phone, ...wa } : null, text: o.body || o.template || o.kind } };

const url = require('url');
const REPO = $env.REPO_DIR || '/home/node/repo';
const L = await import(url.pathToFileURL(REPO + '/automation/lib/w10.mjs').href);
const j = $('Merge context').item.json;
const claimed = !!$('Claim reschedule key (idempotency)').item.json.id;
const start = j.pick.start; const end = new Date(Date.parse(start) + j.br.slot_minutes * 60000).toISOString();
const after = Date.parse(j.bk.ends_at) <= Date.now() || ['no_show', 'attended', 'rescheduled'].includes(j.bk.status);
const d = L.applyReschedule(j.bk, { start, end }, { now_ms: Date.now(), free: !!$json.free, next_slots: $json.next_slots || [], initiated_by: j.source === 'W12' ? 'broker' : 'lead', after_meeting: after, idempotency_key: 'k', seen_keys: new Set(claimed ? [] : ['k']) });
return { json: { ...j, d, new_start: start, new_end: end, rebooked_after_no_show: j.bk.status === 'no_show' } };

const url = require('url');
const REPO = $env.REPO_DIR || '/home/node/repo';
const L = await import(url.pathToFileURL(REPO + '/automation/lib/w10.mjs').href);
const j = $('Decide move (w10.applyReschedule)').item.json;
const label = L.slotLabel(j.new_start);
const lead = { messaging_product: 'whatsapp', to: j.ld.phone, type: 'text', text: { body: 'Done. Your call with ' + String(j.br.contact_person).split(' ')[0] + ' is now ' + label + '.' } };
const notice = L.brokerNotice(j.d.broker_notice, j.ld);
const brokerWindow = Number.isFinite(j.br.last_inbound_ms) && Date.now() - j.br.last_inbound_ms < 86400000;
return [{ json: { to: 'lead', wa: lead } }, { json: { to: 'broker', channel: brokerWindow ? 'whatsapp' : 'email', wa: brokerWindow ? { messaging_product: 'whatsapp', to: j.br.whatsapp_number, type: 'text', text: { body: notice } } : null, email: { to: j.br.email, subject: 'SortMyCover booking moved', body: notice } } }];

const url = require('url');
const REPO = $env.REPO_DIR || '/home/node/repo';
const L = await import(url.pathToFileURL(REPO + '/automation/lib/w10.mjs').href);
const j = $('Decide move (w10.applyReschedule)').item.json;
const slots = (j.d.offer && j.d.offer.length) ? j.d.offer : [];
const rows = slots.map((s) => ({ id: 'slot_' + s.start + ':resched:' + j.bk.id, title: L.slotLabel(s.start).slice(0, 24) }));
return { json: { to: 'lead', wa: rows.length ? { messaging_product: 'whatsapp', to: j.ld.phone, type: 'interactive', interactive: { type: 'list', body: { text: 'Sorry, that time was just taken. Here are the next open times.' }, action: { button: 'See times', sections: [{ title: 'Open times', rows }] } } } : null } };

const url = require('url');
const REPO = $env.REPO_DIR || '/home/node/repo';
const L = await import(url.pathToFileURL(REPO + '/automation/lib/w10.mjs').href);
